// 召唤兽升级: 从 L 级升到 L+1 级所需经验(闭式公式, 已与官方接口逐级验证一致, L: 1..179)
export function petExpStep(L: number): number {
  const n = (L + 1) * (L + 1)
  if (L < 150) return 50 * n
  if (L < 155) return 100 * n
  return 150 * n
}
